import requests
q='(sophocarpine[Title/Abstract]) AND (TLR4[Title/Abstract] OR "toll-like receptor 4"[Title/Abstract] OR steatotic[Title/Abstract] OR hepatocyte[Title/Abstract] OR fatty liver[Title/Abstract])'
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
r=requests.get(u,params={'db':'pubmed','term':q,'retmode':'json','retmax':30},timeout=30)
r.raise_for_status(); ids=r.json()['esearchresult']['idlist']; print('PubMed IDs:',ids)
if ids:
 x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=30).json()['result']
 for i in ids:
  a=x[i]; print(i,a.get('pubdate'),a.get('title'),a.get('fulljournalname'))
else: print('No matching records')
